export const colours=['#ec7540','#13786e','#586cca','#ad4b7f'];
export function freshProfile(name='Signal Scout'){return {name,colour:colours[0],emblem:'star',done:[],attempts:[],created:Date.now(),difficulty:'standard',focus:'auto'};}
export function initialState(){return {version:1,active:0,profiles:[freshProfile()],settings:{scale:1,spacing:0,reduce:false,speech:false,voiceURI:'',speechRate:.85},welcomed:false};}
export function validateSave(s){if(!s||s.version!==1||!Array.isArray(s.profiles)||!s.profiles.length||s.profiles.length>8||!Number.isInteger(s.active)||s.active<0||s.active>=s.profiles.length)throw Error('This is not a supported Hero Academy backup.');for(const p of s.profiles){if(typeof p.name!=='string'||p.name.length<1||p.name.length>24||!colours.includes(p.colour)||!['star','diamond','bolt'].includes(p.emblem)||!Array.isArray(p.done)||p.done.some(x=>!Number.isInteger(x)||x<1||x>12)||new Set(p.done).size!==p.done.length||!Array.isArray(p.attempts)||p.attempts.length>100000)throw Error('The player data is invalid.');if(p.difficulty!==undefined&&!['guided','standard','challenge'].includes(p.difficulty))throw Error('Invalid practice difficulty.');if(p.focus!==undefined&&!['auto','a','i','o','e','u'].includes(p.focus))throw Error('Invalid practice focus.');if(p.adventure!==undefined){const a=p.adventure;if(!a||!Number.isFinite(a.x)||a.x<45||a.x>955||!Number.isFinite(a.y)||a.y<65||a.y>610||!Array.isArray(a.treasures)||a.treasures.some(t=>!Number.isInteger(t)||t<1||t>6)||new Set(a.treasures).size!==a.treasures.length)throw Error('Invalid adventure progress.');}for(const a of p.attempts){if(!a||!Number.isInteger(a.mission)||a.mission<1||a.mission>12||!Number.isInteger(a.task)||a.task<0||a.task>2||typeof a.supported!=='boolean'||typeof a.correct!=='boolean'||!Number.isFinite(a.at))throw Error('Invalid response history.');if(a.skill!==undefined&&(!/^(listen|build|picture):[aioeu]$/.test(a.skill)||typeof a.word!=='string'||a.word.length>20||typeof a.session!=='string'||a.session.length>80||typeof a.taskId!=='string'||a.taskId.length>80))throw Error('Invalid skill record.');}}const c=s.settings;if(!c||![1,1.15,1.3].includes(c.scale)||![0,.04,.08].includes(c.spacing)||typeof c.reduce!=='boolean'||typeof c.speech!=='boolean'||typeof s.welcomed!=='boolean')throw Error('The settings are invalid.');if(c.voiceURI!==undefined&&(typeof c.voiceURI!=='string'||c.voiceURI.length>512))throw Error('The voice setting is invalid.');if(c.speechRate!==undefined&&![.75,.85,1].includes(c.speechRate))throw Error('The speech speed is invalid.');return s;}
export function isUnlocked(profile,id){return id===1||profile.done.includes(id)||profile.done.includes(id-1);}
export function completeMission(profile,id){if(!profile.done.includes(id))profile.done.push(id);}
